pub struct LoadWorkUseCase {
    uow_factory: Box<dyn LoadWorkUnitOfWorkFactoryTrait>,
}

impl LoadWorkUseCase {
    pub fn new(uow_factory: Box<dyn LoadWorkUnitOfWorkFactoryTrait>) -> Self {
        LoadWorkUseCase { uow_factory }
    }

    pub fn execute(&mut self, dto: &LoadWorkDto) -> Result<()> {
        let now = chrono::Utc::now();

        // Stage 1: read + map the file into a neutral graph (no store access yet).
        let shape = skrib::detect_shape(&dto.file_name)
            .with_context(|| format!("inspecting '{}'", dto.file_name))?;
        let loaded = match shape {
            SkribShape::LegacySqlite => {
                let project = legacy::read_project(&dto.file_name)
                    .with_context(|| format!("reading legacy project '{}'", dto.file_name))?;
                legacy_to_loaded(project, now)
            }
            SkribShape::ZipFile | SkribShape::ExplodedFolder => {
                let bundle = skrib::read_bundle(&dto.file_name)
                    .with_context(|| format!("reading project '{}'", dto.file_name))?;
                // Put the images where the editor and the exporters will look
                // for them, before the entities that reference them exist.
                //
                // For an exploded folder this is a no-op by construction: the
                // media directory *is* the project's own `assets/`, so the
                // bytes are already there and nothing is copied. Only a zip
                // needs a working copy extracted.
                let media_dir = skrib_format::media::media_dir(
                    std::path::Path::new(&dto.file_name),
                    &bundle.manifest.work.unique_id,
                    std::path::Path::new(&dto.media_root),
                    &bundle.manifest.work.unique_id,
                );
                crate::work_io::write_asset_bytes(&bundle, &media_dir)
                    .with_context(|| format!("writing media for '{}'", dto.file_name))?;
                skrib::bundle_to_loaded(bundle, &dto.file_name)?
            }
        };

        // Stage 2: materialise entities in a single transaction. Phase 2 (see
        // the multi-Work migration design doc §8): loading a Work no longer
        // closes any other currently-open Work first — the whole point of
        // this phase is that a second simultaneously-open Work stays open.
        // `create_trunk` below appends this Work onto `Root.works` (Phase 0
        // already made that relationship an append, not an overwrite), so
        // materializing this Work cannot disturb another Work's rows.
        //
        // Pinned by `frontend::tests::multi_work_scoping_test::
        // load_work_leaves_every_other_open_work_intact`, which asserts a
        // previously-open Work survives a second `load_work` call untouched —
        // see that test for the both-directions proof.
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        let mat = materialize(&*uow, &loaded)?;
        create_trunk(&*uow, &loaded, &mat, &dto.file_name, shape, now)?;

        uow.commit()?;
        uow.publish_load_work_event(vec![mat.work_id], None);
        Ok(())
    }
}

pub(crate) struct Materialized {
    pub(crate) work_id: EntityId,
    /// ProgressSnapshot orphans built here (they need `item_map` to remap `book_item_ids`),
    /// wired onto the freshly-created WorkInfo in `create_trunk`.
    progress_snapshot_ids: Vec<EntityId>,
}

/// Materialise the Work subtree (lossless: every scalar field, content row,
/// ordering and M2M link is preserved; file ids are remapped to fresh store ids).
///
/// `pub(crate)` (not private): the crate's own two-Works isolation test
/// (`save_load_test.rs`) drives this directly, alongside [`create_trunk`], to
/// seed a SECOND Work into a store that already has one open — Phase 2 of the
/// multi-Work migration removed the "close every other open Work" sweep from
/// the public `execute()` path above, but this direct call is still the only
/// way the test seeds a second Work without going through a full second
/// `execute()` (which would itself just append, per the same Phase 2 change).
///
/// # No `..Default::default()` anywhere in this file
///
/// Every entity literal here spells out all of its fields. That is a deliberate
/// rule, not a style: the struct-update fallback turns "a field was forgotten"
/// from a compile error into silent data loss, and it had already done exactly
/// that to `chapter_mode` — a project saved with flat chapters came back with
/// folder chapters on the next load, for as long as flat chapters had existed,
/// and no test failed because the round-trip projection did not compare the
/// field either. Two other fields (`uid`, `aliases`) carry comments recording
/// the same near-miss.
///
/// So: when a field is added to any entity below, the compiler stops here and
/// makes someone decide what the loader should do with it. Fields that really
/// are meant to start empty say so with an explicit value and a reason.
pub(crate) fn materialize(
    uow: &dyn LoadWorkUnitOfWorkTrait,
    loaded: &LoadedWork,
) -> Result<Materialized> {
    let lw = &loaded.work;
    // Exactly one punctuation row per Work, created unconditionally — the same
    // rule `create_trunk` applies to `Search`, and for the same reason: a
    // project opened without one could never reach the setting at all.
    //
    // A bundle written before the feature existed carries `None`, and gets the
    // entity's own defaults. That is not the same as "the writer turned
    // everything off": `override_app_default` stays false, which is what tells
    // the UI to follow the app-level preference rather than this row.
    // Spelled out field by field rather than with `..sp`, for the reason this
    // whole file avoids `..Default::default()`: a struct-update tail would let a
    // future field be added to `SmartPunctuation` and silently dropped on every
    // load, which is exactly how `chapter_mode` was lost.
    let smart_punctuation =
        uow.create_orphan_smart_punctuation(&match &loaded.smart_punctuation {
            Some(sp) => SmartPunctuation {
                id: 0,
                created_at: sp.created_at,
                updated_at: sp.updated_at,
                override_app_default: sp.override_app_default,
                dashes: sp.dashes,
                ellipsis: sp.ellipsis,
                quotes: sp.quotes,
                quote_style: sp.quote_style.clone(),
                pre_punctuation_spacing: sp.pre_punctuation_spacing,
                dialogue_marker: sp.dialogue_marker,
            },
            None => SmartPunctuation {
                id: 0,
                created_at: lw.created_at,
                updated_at: lw.updated_at,
                // All false, and `override_app_default` false above all: that is
                // what tells the UI to follow the app-level preference rather than
                // this row, so a pre-feature project behaves as if the setting had
                // never been asked about.
                override_app_default: false,
                dashes: false,
                ellipsis: false,
                quotes: false,
                quote_style: common::entities::QuoteStyle::LocaleDefault,
                pre_punctuation_spacing: false,
                dialogue_marker: false,
            },
        })?;

    // The relationship vectors are deliberately empty: `create_orphan_*` makes the
    // rows, and the ids are wired on afterwards by `set_work_relationship`.
    let work = uow.create_orphan_work(&Work {
        id: 0,
        created_at: lw.created_at,
        updated_at: lw.updated_at,
        title: lw.title.clone(),
        author_name: lw.author_name.clone(),
        dict_language: lw.dict_language.clone(),
        // Single heal point for every load (legacy + new-format): preserve the
        // source's stable id, or mint a fresh one when it has none.
        unique_id: if lw.unique_id.is_empty() {
            skrib_format::new_unique_id()
        } else {
            lw.unique_id.clone()
        },
        chapter_mode: lw.chapter_mode.clone(),
        custom_replacement_rules_enabled: lw.custom_replacement_rules_enabled,
        number_chapters: lw.number_chapters,
        part_resets_chapter: lw.part_resets_chapter,
        binders: Vec::new(),
        tags: Vec::new(),
        dict_words: Vec::new(),
        text_replacement_rules: Vec::new(),
        note_templates: Vec::new(),
        assets: Vec::new(),
        // The real id, not a placeholder — which is why the row above is created
        // BEFORE the Work rather than after it, unlike every collection here.
        // A one-to-one field seeds its junction at create time, so two Works
        // both carrying a placeholder 0 would collide on the generated
        // uniqueness check ("SmartPunctuation 0 is already referenced by Work
        // 1") the moment a second project was opened in one session.
        smart_punctuation: smart_punctuation.id,
        trash_infos: Vec::new(),
        paces: Vec::new(),
        comments: Vec::new(),
        footnotes: Vec::new(),
    })?;

    // Tags (file id -> new id).
    let mut tag_map: HashMap<u64, EntityId> = HashMap::new();
    let mut tag_ids: Vec<EntityId> = Vec::new();
    for t in &loaded.tags {
        let created = uow.create_orphan_binder_tag(&BinderTag {
            created_at: t.created_at,
            updated_at: t.updated_at,
            name: t.name.clone(),
            color: t.color.clone(),
            details: t.details.clone(),
            discoverable: t.discoverable,
            id: 0,
        })?;
        tag_map.insert(t.id, created.id);
        tag_ids.push(created.id);
    }

    // Dictionary words.
    let mut dict_word_ids: Vec<EntityId> = Vec::new();
    for w in &loaded.dict_words {
        let created = uow.create_orphan_dict_word(&DictWord {
            created_at: w.created_at,
            updated_at: w.updated_at,
            word: w.word.clone(),
            id: 0,
        })?;
        dict_word_ids.push(created.id);
    }

    // Custom text-replacement rules.
    let mut text_replacement_rule_ids: Vec<EntityId> = Vec::new();
    for r in &loaded.text_replacement_rules {
        let created = uow.create_orphan_text_replacement_rule(&TextReplacementRule {
            created_at: r.created_at,
            updated_at: r.updated_at,
            trigger: r.trigger.clone(),
            replacement: r.replacement.clone(),
            enabled: r.enabled,
            id: 0,
        })?;
        text_replacement_rule_ids.push(created.id);
    }

    // Per-project note templates, in their stored order.
    let mut note_template_ids: Vec<EntityId> = Vec::new();
    for t in &loaded.note_templates {
        let created = uow.create_orphan_note_template(&NoteTemplate {
            created_at: t.created_at,
            updated_at: t.updated_at,
            name: t.name.clone(),
            body: t.body.clone(),
            starred: t.starred,
            id: 0,
        })?;
        note_template_ids.push(created.id);
    }

    // Image metadata rows. The bytes are not stored — they were written to the
    // project's media directory as the bundle was read, and the prose refers to
    // them by content hash.
    let mut asset_ids: Vec<EntityId> = Vec::new();
    for a in &loaded.assets {
        let created = uow.create_orphan_asset(&Asset {
            created_at: a.created_at,
            updated_at: a.updated_at,
            content_hash: a.content_hash.clone(),
            file_name: a.file_name.clone(),
            mime_type: a.mime_type.clone(),
            width: a.width,
            height: a.height,
            byte_size: a.byte_size,
            alt: a.alt.clone(),
            is_cover: a.is_cover,
            id: 0,
        })?;
        asset_ids.push(created.id);
    }

    // Binders -> items -> contents.
    let mut binder_map: HashMap<u64, EntityId> = HashMap::new();
    let mut item_map: HashMap<u64, EntityId> = HashMap::new();
    // Content file id -> fresh store id, so a comment's anchor can be re-pointed at
    // the row it actually annotates. Every `EntityId` is re-minted on load, so the
    // file id a comment was saved against is meaningless until it is remapped here.
    let mut content_map: HashMap<u64, EntityId> = HashMap::new();
    let mut binder_ids: Vec<EntityId> = Vec::new();
    let mut item_tag_links: Vec<(EntityId, Vec<u64>)> = Vec::new();

    for lb in &loaded.binders {
        let created_binder = uow.create_orphan_binder(&Binder {
            // Minting when empty is the final backstop for any load path that
            // failed to supply a uid; without one every row would land in the
            // store sharing a single empty identity.
            uid: common::uid::heal_uid(lb.binder.uid),
            created_at: lb.binder.created_at,
            updated_at: lb.binder.updated_at,
            name: lb.binder.name.clone(),
            activated: lb.binder.activated,
            id: 0,
            // Wired afterwards by `set_binder_relationship`, once the items exist.
            binder_items: Vec::new(),
        })?;
        binder_map.insert(lb.binder.id, created_binder.id);

        let mut item_ids: Vec<EntityId> = Vec::new();
        for li in &lb.items {
            let mut content_ids: Vec<EntityId> = Vec::new();
            for c in &li.contents {
                let created_content = uow.create_orphan_content(&Content {
                    created_at: c.created_at,
                    updated_at: c.updated_at,
                    activated: c.activated,
                    role: c.role.clone(),
                    data: c.data.clone(),
                    id: 0,
                })?;
                content_map.insert(c.id, created_content.id);
                content_ids.push(created_content.id);
            }

            let i = &li.item;
            let created_item = uow.create_orphan_binder_item(&BinderItem {
                // See the binder above: carried explicitly, healed if empty.
                uid: common::uid::heal_uid(i.uid),
                created_at: i.created_at,
                updated_at: i.updated_at,
                title: i.title.clone(),
                sub_title: i.sub_title.clone(),
                role: i.role.clone(),
                sub_role: i.sub_role.clone(),
                label: i.label.clone(),
                activated: i.activated,
                is_favorite: i.is_favorite,
                is_exportable: i.is_exportable,
                exclude_from_numbering: i.exclude_from_numbering,
                indent: i.indent,
                word_count_goal: i.word_count_goal,
                char_count_goal: i.char_count_goal,
                dict_language: i.dict_language.clone(),
                // Covered by `save_load_round_trip_through_store`: aliases were
                // dropped on every load once, with nothing on screen to show for it.
                aliases: i.aliases.clone(),
                id: 0,
                // All three are wired afterwards by `set_binder_item_relationship`,
                // once the contents exist and the file ids have been remapped.
                contents: Vec::new(),
                references: Vec::new(),
                point_of_view: Vec::new(),
                tags: Vec::new(),
            })?;

            if !content_ids.is_empty() {
                uow.set_binder_item_relationship(
                    &created_item.id,
                    &BinderItemRelationshipField::Contents,
                    &content_ids,
                )?;
            }
            item_map.insert(li.item.id, created_item.id);
            if !li.tag_ids.is_empty() {
                item_tag_links.push((created_item.id, li.tag_ids.clone()));
            }
            item_ids.push(created_item.id);
        }

        uow.set_binder_relationship(
            &created_binder.id,
            &BinderRelationshipField::BinderItems,
            &item_ids,
        )?;
        binder_ids.push(created_binder.id);
    }

    // M2M item tags (remap file tag ids -> store ids).
    for (item_id, file_tag_ids) in &item_tag_links {
        let resolved: Vec<EntityId> = file_tag_ids
            .iter()
            .filter_map(|t| tag_map.get(t).copied())
            .collect();
        if !resolved.is_empty() {
            uow.set_binder_item_relationship(
                item_id,
                &BinderItemRelationshipField::Tags,
                &resolved,
            )?;
        }
    }

    // M2M self-references (cross-links), grouped by source.
    let mut refs_by_source: HashMap<EntityId, Vec<EntityId>> = HashMap::new();
    for (src, dst) in &loaded.references {
        if let (Some(&s), Some(&d)) = (item_map.get(src), item_map.get(dst)) {
            refs_by_source.entry(s).or_default().push(d);
        }
    }
    for (s, dsts) in &refs_by_source {
        uow.set_binder_item_relationship(s, &BinderItemRelationshipField::References, dsts)?;
    }

    // Point of view, the same shape: (scene, story-bible item) pairs remapped onto the
    // freshly minted store ids. Kept separate from References rather than folded into it
    // because the two answer different questions — who appears here, versus whose eyes this
    // is told through — and a scene routinely has one without the other.
    let mut pov_by_source: HashMap<EntityId, Vec<EntityId>> = HashMap::new();
    for (src, dst) in &loaded.point_of_view {
        if let (Some(&s), Some(&d)) = (item_map.get(src), item_map.get(dst)) {
            pov_by_source.entry(s).or_default().push(d);
        }
    }
    for (s, dsts) in &pov_by_source {
        uow.set_binder_item_relationship(s, &BinderItemRelationshipField::PointOfView, dsts)?;
    }

    // Trash index (remap origin + trashed targets).
    let mut trash_info_ids: Vec<EntityId> = Vec::new();
    for t in &loaded.trash_infos {
        let origin = if t.origin_binder_id == 0 {
            0
        } else {
            binder_map
                .get(&(t.origin_binder_id as u64))
                .copied()
                .map(|v| v as i64)
                .unwrap_or(0)
        };
        let info = uow.create_orphan_trash_info(&TrashInfo {
            created_at: t.created_at,
            updated_at: t.updated_at,
            trashed_at: t.trashed_at,
            origin_binder_id: origin,
            id: 0,
            // The trashed entity is attached afterwards by `set_trash_info_relationship`
            // — exactly one of the two, once the file ids have been remapped.
            trashed_binder: None,
            trashed_binder_item: None,
        })?;
        if let Some(b) = t.trashed_binder.and_then(|b| binder_map.get(&b).copied()) {
            uow.set_trash_info_relationship(
                &info.id,
                &TrashInfoRelationshipField::TrashedBinder,
                &[b],
            )?;
        }
        if let Some(it) = t
            .trashed_binder_item
            .and_then(|i| item_map.get(&i).copied())
        {
            uow.set_trash_info_relationship(
                &info.id,
                &TrashInfoRelationshipField::TrashedBinderItem,
                &[it],
            )?;
        }
        trash_info_ids.push(info.id);
    }

    // Paces (Work trunk). Children are created first, then the Pace, then wired; the
    // weak `book_item`/`target_item` back-links are remapped through `item_map` (an
    // unresolvable id is simply dropped, same posture as trash back-links).
    let mut pace_ids: Vec<EntityId> = Vec::new();
    for lp in &loaded.paces {
        let mut holiday_ids: Vec<EntityId> = Vec::new();
        for h in &lp.holidays {
            let created = uow.create_orphan_holiday(&Holiday {
                created_at: h.created_at,
                updated_at: h.updated_at,
                label: h.label.clone(),
                start_date: h.start_date,
                end_date: h.end_date,
                id: 0,
            })?;
            holiday_ids.push(created.id);
        }
        let mut milestone_ids: Vec<EntityId> = Vec::new();
        for ms in &lp.milestones {
            let created = uow.create_orphan_milestone(&Milestone {
                created_at: ms.created_at,
                updated_at: ms.updated_at,
                label: ms.label.clone(),
                target_date: ms.target_date,
                target_word_count: ms.target_word_count,
                id: 0,
                // Weak back-link, wired just below through `item_map`; an id that no
                // longer resolves is simply left unset.
                target_item: None,
            })?;
            if let Some(it) = ms.target_item.and_then(|i| item_map.get(&i).copied()) {
                uow.set_milestone_relationship(
                    &created.id,
                    &MilestoneRelationshipField::TargetItem,
                    &[it],
                )?;
            }
            milestone_ids.push(created.id);
        }
        let pace = uow.create_orphan_pace(&Pace {
            created_at: lp.created_at,
            updated_at: lp.updated_at,
            start_date: lp.start_date,
            end_date: lp.end_date,
            weekday_mask: lp.weekday_mask,
            active: lp.active,
            id: 0,
            // Book back-link and both child collections are wired after creation.
            book_item: None,
            holidays: Vec::new(),
            milestones: Vec::new(),
        })?;
        if let Some(bi) = lp.book_item.and_then(|i| item_map.get(&i).copied()) {
            uow.set_pace_relationship(&pace.id, &PaceRelationshipField::BookItem, &[bi])?;
        }
        if !holiday_ids.is_empty() {
            uow.set_pace_relationship(&pace.id, &PaceRelationshipField::Holidays, &holiday_ids)?;
        }
        if !milestone_ids.is_empty() {
            uow.set_pace_relationship(
                &pace.id,
                &PaceRelationshipField::Milestones,
                &milestone_ids,
            )?;
        }
        pace_ids.push(pace.id);
    }

    // Comments (Work trunk). Replies are created first, then the Comment, then the
    // two relationships. The `content` back-link is weak and remapped through
    // `content_map`: an anchor whose Content no longer resolves is left unset and the
    // row is flagged orphaned here rather than dropped — which is also exactly the
    // state a comment restored from the bundle-root orphanage arrives in.
    let mut comment_ids: Vec<EntityId> = Vec::new();
    for lc in &loaded.comments {
        let mut reply_ids: Vec<EntityId> = Vec::new();
        for r in &lc.replies {
            let created = uow.create_orphan_comment_reply(&CommentReply {
                created_at: r.created_at,
                updated_at: r.updated_at,
                author_name: r.author_name.clone(),
                body: r.body.clone(),
                id: 0,
            })?;
            reply_ids.push(created.id);
        }

        let resolved_content = lc.content.and_then(|i| content_map.get(&i).copied());
        // A comment that named a Content the bundle no longer contains has lost its
        // anchor for good — record *why*, so the dock can say so instead of showing a
        // thread that silently points nowhere.
        let lost_target = lc.content.is_some() && resolved_content.is_none();
        let created = uow.create_orphan_comment(&Comment {
            created_at: lc.created_at,
            updated_at: lc.updated_at,
            kind: lc.kind.clone(),
            author_name: lc.author_name.clone(),
            body: lc.body.clone(),
            resolved: lc.resolved,
            orphaned: lc.orphaned || lost_target || lc.content.is_none(),
            orphan_reason: if lost_target || lc.content.is_none() {
                common::entities::CommentOrphanReason::TargetDeleted
            } else {
                lc.orphan_reason.clone()
            },
            range_start: lc.range_start,
            range_length: lc.range_length,
            quote_prefix: lc.quote_prefix.clone(),
            quote_exact: lc.quote_exact.clone(),
            quote_exact_truncated: lc.quote_exact_truncated,
            quote_suffix: lc.quote_suffix.clone(),
            block_ordinal_hint: lc.block_ordinal_hint,
            id: 0,
            // Both wired after creation.
            content: None,
            replies: Vec::new(),
        })?;
        if let Some(cid) = resolved_content {
            uow.set_comment_relationship(&created.id, &CommentRelationshipField::Content, &[cid])?;
        }
        if !reply_ids.is_empty() {
            uow.set_comment_relationship(
                &created.id,
                &CommentRelationshipField::Replies,
                &reply_ids,
            )?;
        }
        comment_ids.push(created.id);
    }

    // Footnotes (Work trunk). Far less to do than a comment: no replies, no quote,
    // no stored orphan state. The `content` back-link is weak and remapped the same
    // way, and a note whose Content no longer resolves simply arrives unanchored —
    // it keeps its text and the dock reports it, because those words are the book's.
    let mut footnote_ids: Vec<EntityId> = Vec::new();
    for lf in &loaded.footnotes {
        let resolved_content = lf.content.and_then(|i| content_map.get(&i).copied());
        let created = uow.create_orphan_footnote(&common::entities::Footnote {
            created_at: lf.created_at,
            updated_at: lf.updated_at,
            label: lf.label.clone(),
            body: lf.body.clone(),
            id: 0,
            // Wired after creation.
            content: None,
        })?;
        if let Some(cid) = resolved_content {
            uow.set_footnote_relationship(
                &created.id,
                &common::direct_access::footnote::FootnoteRelationshipField::Content,
                &[cid],
            )?;
        }
        footnote_ids.push(created.id);
    }

    // Work's owned collections.
    uow.set_work_relationship(&work.id, &WorkRelationshipField::Binders, &binder_ids)?;
    if !footnote_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Footnotes, &footnote_ids)?;
    }
    if !tag_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Tags, &tag_ids)?;
    }
    if !dict_word_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::DictWords, &dict_word_ids)?;
    }
    if !text_replacement_rule_ids.is_empty() {
        uow.set_work_relationship(
            &work.id,
            &WorkRelationshipField::TextReplacementRules,
            &text_replacement_rule_ids,
        )?;
    }
    if !note_template_ids.is_empty() {
        uow.set_work_relationship(
            &work.id,
            &WorkRelationshipField::NoteTemplates,
            &note_template_ids,
        )?;
    }
    if !asset_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Assets, &asset_ids)?;
    }
    // Unconditional, unlike every collection above: there is always exactly one
    // punctuation row, so there is no "empty" case to skip.
    uow.set_work_relationship(
        &work.id,
        &WorkRelationshipField::SmartPunctuation,
        &[smart_punctuation.id],
    )?;
    // Trash lives under the Work trunk (post-reparent).
    if !trash_info_ids.is_empty() {
        uow.set_work_relationship(
            &work.id,
            &WorkRelationshipField::TrashInfos,
            &trash_info_ids,
        )?;
    }
    if !pace_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Paces, &pace_ids)?;
    }
    if !comment_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Comments, &comment_ids)?;
    }

    // ProgressSnapshots — created here (needs `item_map` to remap the per-Book breakdown
    // ids), wired onto the fresh WorkInfo back in `create_trunk`. Both parallel arrays are
    // filtered in lockstep so an unresolvable book id drops its paired count too.
    let mut progress_snapshot_ids: Vec<EntityId> = Vec::new();
    for s in &loaded.progress_snapshots {
        let (book_ids, book_counts): (Vec<u64>, Vec<i64>) = s
            .book_item_ids
            .iter()
            .zip(&s.book_word_counts)
            .filter_map(|(fid, wc)| item_map.get(fid).copied().map(|id| (id, *wc)))
            .unzip();
        let created = uow.create_orphan_progress_snapshot(&ProgressSnapshot {
            created_at: s.created_at,
            updated_at: s.updated_at,
            day: s.day,
            total_word_count: s.total_word_count,
            total_char_count: s.total_char_count,
            id: 0,
            book_item_ids: book_ids,
            book_word_counts: book_counts,
        })?;
        progress_snapshot_ids.push(created.id);
    }

    Ok(Materialized {
        work_id: work.id,
        progress_snapshot_ids,
    })
}

/// Build the non-undoable trunk: System + RecentWork + WorkInfo (records the
/// opened path and its shape) + Root.
///
/// `pub(crate)` — see [`materialize`]'s doc comment for why.
pub(crate) fn create_trunk(
    uow: &dyn LoadWorkUnitOfWorkTrait,
    loaded: &LoadedWork,
    mat: &Materialized,
    file_name: &str,
    shape: SkribShape,
    now: DateTime<Utc>,
) -> Result<()> {
    // Reuse the single shared System (seeded by `initialize_app`, or created by a
    // prior load/new); create one only if absent (e.g. a load before any init).
    let system_id = match uow.get_all_system()?.into_iter().next() {
        Some(system) => system.id,
        None => {
            uow.create_orphan_system(&System {
                id: 0,
                created_at: now,
                updated_at: now,
                // Both fill up as projects are opened; a fresh System owns nothing.
                recent_works: Vec::new(),
                work_infos: Vec::new(),
            })?
            .id
        }
    };

    let recent = uow.create_orphan_recent_work(&RecentWork {
        created_at: now,
        updated_at: now,
        title: loaded.work.title.clone(),
        last_opened_at: now,
        absolute_path: loaded.absolute_path.clone(),
        id: 0,
    })?;
    // Append to the existing recents rather than replacing them — the list
    // accumulates across opens (`close_work` leaves `RecentWork` rows in place).
    let mut recent_ids =
        uow.get_system_relationship(&system_id, &SystemRelationshipField::RecentWorks)?;
    recent_ids.push(recent.id);
    uow.set_system_relationship(
        &system_id,
        &SystemRelationshipField::RecentWorks,
        &recent_ids,
    )?;

    let work_shape = match shape {
        SkribShape::ExplodedFolder => WorkShape::Folder,
        SkribShape::ZipFile | SkribShape::LegacySqlite => WorkShape::Zip,
    };
    // Every Work gets its live Search surface, created eagerly alongside its
    // WorkInfo. `run_search` resolves it through `WorkInfo.search`, so a project
    // opened without one could never search. `Search`/`SearchResult` are
    // `undoable: false` and never round-trip through .skrib — this is a business
    // surface rebuilt per session, not persisted state. (The *parameters* that must
    // survive a restart live in the UI's `search.toml`, not here.)
    let search = uow.create_orphan_search(&Search {
        id: 0,
        created_at: now,
        updated_at: now,
        // A blank search row, every field at rest. It is deliberately NOT a
        // usable search: the scope flags are all false, so this row would match
        // nothing as it stands. That is correct — the UI pushes the writer's real
        // parameters (restored from `search.toml`) before anything is ever run,
        // and seeding a scope here would silently override what they had chosen.
        // Written out so that adding a facet forces that decision at this line
        // instead of defaulting it out of sight.
        query: String::new(),
        case_sensitive: false,
        whole_word: false,
        diacritic_sensitive: false,
        facets: Vec::new(),
        search_body: false,
        search_titles: false,
        search_synopsis: false,
        search_labels: false,
        include_trashed: false,
        truncated: false,
        results: Vec::new(),
    })?;
    let work_info = uow.create_orphan_work_info(&WorkInfo {
        created_at: now,
        updated_at: now,
        file_name: Some(file_name.to_string()),
        shape: work_shape,
        id: 0,
        // All three are wired just below: the Work it describes, the Search
        // created above, and the snapshots materialised from the bundle.
        work: None,
        search: 0,
        progress_snapshots: Vec::new(),
    })?;
    // Per-open-Work session info: link under System.work_infos and point it at
    // its Work (the multi-Work discriminator). Append, not replace — mirrors the
    // RecentWorks/Root.Works idiom below: with the "close every other open Work"
    // sweep removed, another Work's WorkInfo can already be linked here, and a
    // blind `set` would silently unlink it while that Work is still open.
    let mut work_info_ids =
        uow.get_system_relationship(&system_id, &SystemRelationshipField::WorkInfos)?;
    work_info_ids.push(work_info.id);
    uow.set_system_relationship(
        &system_id,
        &SystemRelationshipField::WorkInfos,
        &work_info_ids,
    )?;
    uow.set_work_info_relationship(
        &work_info.id,
        &WorkInfoRelationshipField::Search,
        &[search.id],
    )?;
    uow.set_work_info_relationship(
        &work_info.id,
        &WorkInfoRelationshipField::Work,
        &[mat.work_id],
    )?;
    // Hydrate the daily history onto the fresh WorkInfo (the reach-through-WorkInfo the
    // save path mirrors). The snapshot orphans were built in `materialize`.
    if !mat.progress_snapshot_ids.is_empty() {
        uow.set_work_info_relationship(
            &work_info.id,
            &WorkInfoRelationshipField::ProgressSnapshots,
            &mat.progress_snapshot_ids,
        )?;
    }

    // Reuse the single shared Root (one per process; multiple Works hang off it).
    let root_id = match uow.get_all_root()?.into_iter().next() {
        Some(root) => root.id,
        None => {
            uow.create_orphan_root(&Root {
                id: 0,
                created_at: now,
                updated_at: now,
                // Both wired afterwards: one System, and the open Works under it.
                system: 0,
                works: Vec::new(),
            })?
            .id
        }
    };
    uow.set_root_relationship(&root_id, &RootRelationshipField::System, &[system_id])?;
    // Append, not replace — mirrors the RecentWorks idiom just above. Inert under
    // today's single-Work-at-a-time UI (the loop in `execute` already closed every
    // previously-open Work, so this list is empty on entry) but load-bearing the
    // moment two Works genuinely coexist, e.g. the crate's own two-Works isolation
    // test, which seeds a second Work directly via `materialize`/`create_trunk`
    // without going through `execute`'s close step.
    let mut work_ids = uow.get_root_relationship(&root_id, &RootRelationshipField::Works)?;
    work_ids.push(mat.work_id);
    uow.set_root_relationship(&root_id, &RootRelationshipField::Works, &work_ids)?;
    Ok(())
}

/// Adapt the legacy SQLite reader's output to the neutral graph, assigning
/// internally-consistent file ids and reproducing the historic defaults
/// (`is_exportable = true`, trashed items stay in place indexed by TrashInfo).
fn legacy_to_loaded(p: legacy::LegacyProject, now: DateTime<Utc>) -> LoadedWork {
    use skrib::{LoadedBinder, LoadedItem, LoadedTrash};

    let mut next_id: u64 = 1;
    let mut fresh = || {
        let v = next_id;
        next_id += 1;
        v
    };

    let work = Work {
        id: fresh(),
        created_at: now,
        updated_at: now,
        title: p.title.clone(),
        author_name: p.author.clone(),
        // The legacy DB stores one space-separated string — split it here, exactly as the
        // pre-v4 bundle deserializer does, so both legacy paths agree.
        dict_language: skribisto_model::language::parse_legacy_list(&p.dict_language),
        // Carry the legacy id through; empty → minted at `materialize`.
        unique_id: p.unique_id.clone(),
        // A legacy project predates all three: it has no chapter-mode concept
        // (folder chapters are the only shape it can express), no lexicon, and
        // no punctuation house style.
        chapter_mode: common::entities::ChapterMode::Folder,
        custom_replacement_rules_enabled: false,
        // The legacy format has no numbering settings. Numbering on, parts not
        // resetting, is what the old app did and what a new project does.
        number_chapters: true,
        part_resets_chapter: false,
        // `LoadedWork` carries the children in its own ordered vectors.
        binders: Vec::new(),
        tags: Vec::new(),
        dict_words: Vec::new(),
        text_replacement_rules: Vec::new(),
        note_templates: Vec::new(),
        assets: Vec::new(),
        // `materialize` mints the default row — see the note at its own literal.
        smart_punctuation: 0,
        trash_infos: Vec::new(),
        paces: Vec::new(),
        // A legacy project has no comments to carry: the C++ Skribisto had no
        // annotation feature at all (no comment table in any legacy schema), so
        // this is genuinely empty rather than not-yet-read.
        comments: Vec::new(),
        footnotes: Vec::new(),
    };

    let mut tag_map: HashMap<i64, u64> = HashMap::new();
    let tags: Vec<BinderTag> = p
        .tags
        .iter()
        .map(|(old, t)| {
            let fid = fresh();
            tag_map.insert(*old, fid);
            BinderTag {
                id: fid,
                created_at: now,
                updated_at: now,
                name: t.name.clone(),
                color: t.color.clone(),
                // The legacy schema has no equivalent of either: a pre-3.0 project
                // never had tag descriptions, and nothing in it was story-bible
                // material for the mention index. Its `t_text_color` is deliberately
                // dropped — text colour is derived from `color` at render time now.
                details: String::new(),
                discoverable: false,
            }
        })
        .collect();

    let dict_words: Vec<DictWord> = p
        .dict_words
        .iter()
        .map(|w| DictWord {
            id: fresh(),
            created_at: now,
            updated_at: now,
            word: w.clone(),
        })
        .collect();

    let mut item_map: HashMap<i64, u64> = HashMap::new();
    let mut trash_infos: Vec<LoadedTrash> = Vec::new();
    let mut binders: Vec<LoadedBinder> = Vec::new();

    for b in &p.binders {
        let bfid = fresh();
        if !b.activated {
            trash_infos.push(LoadedTrash {
                created_at: now,
                updated_at: now,
                trashed_at: now,
                origin_binder_id: 0,
                trashed_binder: Some(bfid),
                trashed_binder_item: None,
            });
        }

        let mut items: Vec<LoadedItem> = Vec::new();
        for it in &b.items {
            let ifid = fresh();
            item_map.insert(it.old_id, ifid);

            let contents: Vec<Content> = it
                .contents
                .iter()
                .map(|c| Content {
                    id: fresh(),
                    created_at: now,
                    updated_at: now,
                    activated: it.activated,
                    role: c.role.clone(),
                    data: c.data.clone(),
                })
                .collect();

            if !it.activated {
                trash_infos.push(LoadedTrash {
                    created_at: now,
                    updated_at: now,
                    trashed_at: now,
                    origin_binder_id: bfid as i64,
                    trashed_binder: None,
                    trashed_binder_item: Some(ifid),
                });
            }

            let tag_ids: Vec<u64> = it
                .tag_old_ids
                .iter()
                .filter_map(|t| tag_map.get(t).copied())
                .collect();

            items.push(LoadedItem {
                item: BinderItem {
                    id: ifid,
                    // The legacy path builds its graph directly and never
                    // constructs a `WorkBundle`, so `migrate_bundle`'s minting
                    // step never sees these rows — mint here instead.
                    uid: common::uid::new_uid(),
                    created_at: now,
                    updated_at: now,
                    title: it.title.clone(),
                    sub_title: it.sub_title.clone(),
                    role: it.role.clone(),
                    sub_role: it.sub_role.clone(),
                    label: it.label.clone(),
                    activated: it.activated,
                    is_exportable: true,
                    exclude_from_numbering: false,
                    indent: it.indent,
                    word_count_goal: it.word_count_goal,
                    char_count_goal: it.char_count_goal,
                    // The legacy format has none of these: no per-item language,
                    // no aliases. Its favourites flag is not carried either.
                    is_favorite: false,
                    dict_language: Vec::new(),
                    aliases: Vec::new(),
                    // Carried beside the item, in `LoadedItem`.
                    contents: Vec::new(),
                    references: Vec::new(),
                    point_of_view: Vec::new(),
                    tags: Vec::new(),
                },
                contents,
                tag_ids,
            });
        }

        binders.push(LoadedBinder {
            binder: Binder {
                id: bfid,
                // See the item above — the legacy path mints its own.
                uid: common::uid::new_uid(),
                created_at: now,
                updated_at: now,
                name: b.name.clone(),
                activated: b.activated,
                // Carried beside the binder, in `LoadedBinder`.
                binder_items: Vec::new(),
            },
            items,
        });
    }

    let references: Vec<(u64, u64)> = p
        .references
        .iter()
        .filter_map(
            |(src, dst)| match (item_map.get(src).copied(), item_map.get(dst).copied()) {
                (Some(s), Some(d)) => Some((s, d)),
                _ => None,
            },
        )
        .collect();

    LoadedWork {
        work,
        tags,
        dict_words,
        // Legacy (pre-.skrib-v4) SQLite projects predate this feature entirely.
        text_replacement_rules: Vec::new(),
        // Legacy projects have no templates either.
        note_templates: Vec::new(),
        assets: Vec::new(),
        // Likewise — and `None` rather than an all-false row, so `materialize`
        // treats it as "never configured" and leaves the project following the
        // app default instead of recording a house style nobody chose.
        smart_punctuation: None,
        binders,
        trash_infos,
        // Legacy projects never had a writing plan.
        paces: Vec::new(),
        progress_snapshots: Vec::new(),
        // Nor comments: the C++ Skribisto had no annotation feature, and no legacy
        // schema version carries a comment table.
        comments: Vec::new(),
        footnotes: Vec::new(),
        references,
        // Legacy projects had no point-of-view concept.
        point_of_view: Vec::new(),
        absolute_path: p.absolute_path.clone(),
    }
}

#[cfg(test)]
mod legacy_uid_tests {
    use super::*;

    /// The legacy SQLite path builds its graph directly and never constructs a
    /// `WorkBundle`, so `migrate_bundle`'s minting step never sees these rows.
    /// A fix confined to `migration.rs` would silently miss every legacy
    /// project -- this pins the independent mint.
    #[test]
    fn a_legacy_project_gets_a_distinct_uid_for_every_row() {
        use legacy::{LegacyBinder, LegacyItem, LegacyProject};

        let item = |old_id: i64, title: &str| LegacyItem {
            old_id,
            title: title.to_string(),
            sub_title: String::new(),
            role: common::entities::BinderItemRole::Item,
            sub_role: common::entities::BinderItemSubRole::Scene,
            label: String::new(),
            activated: true,
            indent: 0,
            word_count_goal: 0,
            char_count_goal: 0,
            contents: Vec::new(),
            tag_old_ids: Vec::new(),
        };
        let project = LegacyProject {
            title: "Old Novel".into(),
            author: "A".into(),
            dict_language: "en-US".into(),
            unique_id: String::new(),
            absolute_path: "/tmp/old.skrib".into(),
            tags: Vec::new(),
            dict_words: Vec::new(),
            binders: vec![LegacyBinder {
                name: "Manuscript".into(),
                is_note: false,
                activated: true,
                items: vec![item(1, "One"), item(2, "Two"), item(3, "Three")],
            }],
            references: Vec::new(),
        };

        let loaded = legacy_to_loaded(project, chrono::Utc::now());

        let mut seen = std::collections::HashSet::new();
        for b in &loaded.binders {
            assert!(!b.binder.uid.is_nil(), "legacy binder left unidentified");
            assert!(
                seen.insert(b.binder.uid),
                "duplicate uid across legacy rows"
            );
            for i in &b.items {
                assert!(!i.item.uid.is_nil(), "legacy item left unidentified");
                assert!(seen.insert(i.item.uid), "duplicate uid across legacy rows");
            }
        }
        assert_eq!(seen.len(), 4, "one binder + three items, all distinct");
    }
}
